package com.aetherforge.api;import com.aetherforge.repo.OperationalRepository;import com.aetherforge.service.AutonomousService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class OperationsController {private final OperationalRepository r;private final AutonomousService auto;public OperationsController(OperationalRepository r,AutonomousService a){this.r=r;this.auto=a;}@GetMapping("/alerts") List<Map<String,Object>> alerts(){return r.alerts();}@PatchMapping("/alerts/{id}") Map<String,Object> alert(@PathVariable String id,@RequestParam String status){r.updateAlert(id,status);return Map.of("ok",true);}@GetMapping("/maintenance") List<Map<String,Object>> maintenance(){return r.maintenance();}@GetMapping("/production") List<Map<String,Object>> production(){return r.production();}@GetMapping("/energy") List<Map<String,Object>> energy(){return r.energy();}@GetMapping("/predictions") List<Map<String,Object>> predictions(){return r.predictions();}@GetMapping("/recommendations") List<Map<String,Object>> recs(){return r.recommendations();}@GetMapping("/autonomous") List<Map<String,Object>> auto(){return r.autonomous();}@PostMapping("/autonomous/{id}/decision") @PreAuthorize("hasAnyRole('ENGINEER','ADMIN')") Map<String,Object> decide(@PathVariable String id,@RequestParam String decision){var a=SecurityContextHolder.getContext().getAuthentication();String role=a.getAuthorities().iterator().next().getAuthority().replace("ROLE_","");return auto.decide(id,decision,a.getName(),role);}@PostMapping("/autonomous/{id}/execute") @PreAuthorize("hasAnyRole('ENGINEER','ADMIN')") Map<String,Object> execute(@PathVariable String id){var a=SecurityContextHolder.getContext().getAuthentication();String role=a.getAuthorities().iterator().next().getAuthority().replace("ROLE_","");return auto.execute(id,a.getName(),role);}@GetMapping("/audit") @PreAuthorize("hasAnyRole('ADMIN','ENGINEER')") List<Map<String,Object>> audit(){return r.audit();}}
